# Local accessibility loss: keep command and wait instead of releasing it.
s=rep(s,'''    private void holdLeaseForAccessibility(String profileId, JSONObject command, ApiClient api) {\n        boolean granted = BlueAccessibilityService.isEnabled(this);\n        String reason = granted\n                ? "Accessibilité Android autorisée mais service en reconnexion; aucune composition financière avant reconnexion."\n                : "Accessibilité Android désactivée; réactivation utilisateur requise avant achat/vente.";\n        releaseUnexecutedLease(profileId, command, api, reason);\n        apiRetryAtByProfile.put(profileId, System.currentTimeMillis() + (granted ? 5_000L : 30_000L));\n        updateNotification(robotSummary(granted\n                ? "Accessibilité en reconnexion — Robot conservé, reprise automatique dès retour du service"\n                : "Accessibilité désactivée — Robot conservé, achat/vente en attente de réactivation"));\n    }''','''    private void holdLeaseForAccessibility(String profileId, JSONObject command, ApiClient api) {\n        boolean granted = BlueAccessibilityService.isEnabled(this);\n        String reason = granted\n                ? "Accessibilité Android autorisée mais service en reconnexion; aucune composition financière avant reconnexion."\n                : "Accessibilité Android désactivée; réactivation utilisateur requise avant achat/vente.";\n        if (OfflineLedgerDb.isLocal(command)) {\n            // The local command belongs to this SIM. Never throw it away because Android temporarily\n            // detached Accessibility: keep LEASED and wait for onServiceConnected().\n            PendingCommandStore.updateState(this, profileId, PendingCommandStore.LEASED);\n            OfflineLedgerDb.get(this).record(this, profileId, command, "WAITING_ACCESSIBILITY", reason, "", true);\n        } else {\n            releaseUnexecutedLease(profileId, command, api, reason);\n        }\n        apiRetryAtByProfile.put(profileId, System.currentTimeMillis() + (granted ? 5_000L : 30_000L));\n        updateNotification(robotSummary(granted\n                ? "Accessibilité en reconnexion — file conservée, reprise automatique"\n                : "Accessibilité désactivée — file conservée; réactivation utilisateur nécessaire"));\n    }''','accessibility local preservation')
# Secure/simple lock: local intent waits; server lease still released safely.
s=rep(s,'''    private void releaseLockedLease(String profileId, JSONObject command, ApiClient api) {\n        boolean secure = DeviceLockState.isSecurelyLocked(this);\n        String reason = secure\n                ? "Écran protégé par un verrou sécurisé. Déverrouillage humain obligatoire."\n                : "Le verrou simple n’a pas pu être libéré proprement lors de la tentative ponctuelle.";\n        try {\n            api.releaseCommand(command, reason + " La commande reste dans la file et pourra être reprise.");\n        } catch (Exception ignored) {\n            // Un ancien serveur relâchera lui-même le lease à son expiration.\n        }\n        PendingCommandStore.clear(this, profileId);\n        releaseCommandWakeLock();''','''    private void releaseLockedLease(String profileId, JSONObject command, ApiClient api) {\n        boolean secure = DeviceLockState.isSecurelyLocked(this);\n        String reason = secure\n                ? "Écran protégé par un verrou sécurisé. Déverrouillage humain obligatoire."\n                : "Le verrou simple n’a pas pu être libéré proprement lors de la tentative ponctuelle.";\n        if (OfflineLedgerDb.isLocal(command)) {\n            PendingCommandStore.updateState(this, profileId, PendingCommandStore.LEASED);\n            OfflineLedgerDb.get(this).record(this, profileId, command, "WAITING_UNLOCK", reason, "", true);\n        } else {\n            try { api.releaseCommand(command, reason + " La commande reste dans la file et pourra être reprise."); }\n            catch (Exception ignored) {}\n            PendingCommandStore.clear(this, profileId);\n        }\n        releaseCommandWakeLock();''','lock local preservation')
# Readiness release: local temporary condition waits; hard mismatches are handled separately.
s=rep(s,'''    private void releaseUnexecutedLease(String profileId, JSONObject command, ApiClient api,\n                                        String reason) {\n        try {\n            api.releaseCommand(command, "Robot non éligible avant composition : " + reason);\n        } catch (Exception ignored) {\n            // Le lease serveur expirera sans DIALING; il pourra alors être repris sans double débit.\n        }\n        PendingCommandStore.clear(this, profileId);\n        releaseCommandWakeLock();\n    }''','''    private void releaseUnexecutedLease(String profileId, JSONObject command, ApiClient api,\n                                        String reason) {\n        if (OfflineLedgerDb.isLocal(command)) {\n            PendingCommandStore.updateState(this, profileId, PendingCommandStore.LEASED);\n            OfflineLedgerDb.get(this).record(this, profileId, command, "WAITING_READINESS", reason, "", true);\n        } else {\n            try { api.releaseCommand(command, "Robot non éligible avant composition : " + reason); }\n            catch (Exception ignored) {}\n            PendingCommandStore.clear(this, profileId);\n        }\n        releaseCommandWakeLock();\n    }''','readiness local preservation')
# Replace finishCommand with local-first durable result path while keeping server command semantics.
pattern=r'''    private void finishCommand\(String profileId, boolean success, String errorCode,\n                               String message, String transactionId\) \{.*?\n    \}\n\n    private void scheduleOverlapAuditAfterFinancial'''
replacement='''    private void finishCommand(String profileId, boolean success, String errorCode,\n                               String message, String transactionId) {\n        if (profileId == null || profileId.isEmpty()) return;\n        JSONObject command = PendingCommandStore.get(this, profileId);\n        if (command == null) return;\n        String code = errorCode == null ? "" : errorCode;\n        String state = success ? "SUCCEEDED"\n                : ("WRONG_PIN".equals(code) || "PIN_BLOCKED".equals(code)) ? "BLOCKED"\n                : ("RESULT_TIMEOUT".equals(code) || "USER_CANCELLED_UNCERTAIN".equals(code)\n                || "CONCURRENT_COMMAND_RECOVERY".equals(code)) ? "UNKNOWN" : "FAILED";\n        if ("WRONG_PIN".equals(code)) AppConfig.setPinBlocked(this, profileId, true);\n        String detail = message == null ? "" : message;\n        if (!code.isEmpty()) detail = code + " — " + detail;\n        JSONObject localEvidence = OfflineLedgerDb.get(this).record(this, profileId, command, state, detail,\n                transactionId == null ? "" : transactionId, true);\n        boolean localOnly = OfflineLedgerDb.isLocal(command);\n        boolean reported = localOnly;\n        if (!localOnly) {\n            try {\n                ApiClient.forProfile(this, profileId).sendEvent(command, state, detail,\n                        transactionId == null ? "" : transactionId);\n                reported = true;\n                OfflineLedgerDb.get(this).markSynced(localEvidence.optString("event_id", ""));\n            } catch (Exception ignored) {\n                try {\n                    command.put("local_state", PendingCommandStore.REPORT_PENDING);\n                    command.put("final_state", state);\n                    command.put("final_message", message == null ? "" : message);\n                    command.put("final_error_code", code);\n                    command.put("final_transaction_id", transactionId == null ? "" : transactionId);\n                    command.put("state_changed_at", System.currentTimeMillis());\n                    PendingCommandStore.save(this, profileId, command);\n                } catch (Exception ignoredAgain) {}\n            }\n        }\n        if (success && "MODIFY_PIN_LOCAL".equals(UssdCommandFactory.operation(command))) {\n            try { PendingPinChangeStore.commit(this, profileId); } catch (Exception ignored) {}\n        }\n        if (success && CommandExecutionPolicy.isFinancial(UssdCommandFactory.operation(command))) {\n            scheduleOverlapAuditAfterFinancial(profileId);\n        }\n        if (reported) PendingCommandStore.clear(this, profileId);\n        if (localOnly) {\n            OfflineSyncManager.flushAsync(this);\n            if (BirRelayManager.isEnabled(this)) BirRelayManager.get(this).kick();\n        }\n        lastCommandFinishedAt = System.currentTimeMillis();\n        releaseCommandWakeLock();\n        BlueAccessibilityService.kick(this);\n        updateNotification(localOnly\n                ? (success ? "Commande locale réussie — synchronisation opportuniste" : "Résultat local conservé — à rapprocher/synchroniser")\n                : reported ? (success ? "Dernière commande réussie — " + AppConfig.nodeCode(this, profileId)\n                : (AppConfig.pinBlocked(this, profileId) ? "PIN incorrect — Robot bloqué"\n                : "Dernière commande à vérifier — " + AppConfig.nodeCode(this, profileId)))\n                : "Résultat obtenu — synchronisation en attente");\n        scheduleCycle(reported ? 1_000L : 15_000L);\n    }\n\n    private void scheduleOverlapAuditAfterFinancial'''
s=sub(s,pattern,replacement,'finishCommand',re.S)
