insert='''        @JavascriptInterface\n        public String getUiLanguage() {\n            return AppConfig.prefs(MainActivity.this).getString(UI_LANGUAGE_KEY, "fr");\n        }\n\n        @JavascriptInterface\n        public String getOfflineStatus() {\n            JSONObject out = OfflineLedgerDb.get(MainActivity.this).stats();\n            try {\n                out.put("relay_enabled", BirRelayManager.isEnabled(MainActivity.this));\n                out.put("robot_local_capable", AppConfig.isRobotMode(MainActivity.this));\n                out.put("directory_age_ms", OfflineDirectoryStore.ageMs(MainActivity.this, AppConfig.profileId(MainActivity.this)));\n            } catch (Exception ignored) {}\n            return out.toString();\n        }\n\n        @JavascriptInterface\n        public String getRelayStatus() { return BirRelayManager.status(MainActivity.this).toString(); }\n\n        @JavascriptInterface\n        public void setRelayEnabled(boolean enabled) {\n            runOnUiThread(() -> {\n                if (enabled && !BirRelayManager.permissionsReady(MainActivity.this)) {\n                    prepareRelayPermissions();\n                    return;\n                }\n                BirRelayManager.setEnabled(MainActivity.this, enabled);\n                toast(enabled ? ui("B.I.R. Relay activé.", "B.I.R. Relay enabled.")\n                        : ui("B.I.R. Relay désactivé.", "B.I.R. Relay disabled."));\n            });\n        }\n\n        @JavascriptInterface\n        public void startRelayExchange() {\n            runOnUiThread(() -> {\n                if (!BirRelayManager.permissionsReady(MainActivity.this)) { prepareRelayPermissions(); return; }\n                BirRelayManager.setEnabled(MainActivity.this, true);\n                BirRelayManager.get(MainActivity.this).kick();\n                toast(ui("Recherche Relay lancée pendant une courte fenêtre.", "Relay nearby exchange window started."));\n            });\n        }\n\n        @JavascriptInterface\n        public void cacheNetworkSnapshot(String json) {\n            try { OfflineDirectoryStore.save(MainActivity.this, AppConfig.profileId(MainActivity.this), new JSONObject(json)); }\n            catch (Exception ignored) {}\n        }\n\n'''+anchor
