# Add relay permission helper before openAccessibilitySettings.
anchor='''    private void openAccessibilitySettings() {'''
helper='''    private void prepareRelayPermissions() {\n        java.util.ArrayList<String> permissions = new java.util.ArrayList<>();\n        if (Build.VERSION.SDK_INT >= 33) {\n            if (checkSelfPermission("android.permission.NEARBY_WIFI_DEVICES") != PackageManager.PERMISSION_GRANTED)\n                permissions.add("android.permission.NEARBY_WIFI_DEVICES");\n        } else if (checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION) != PackageManager.PERMISSION_GRANTED) {\n            permissions.add(Manifest.permission.ACCESS_FINE_LOCATION);\n        }\n        if (Build.VERSION.SDK_INT >= 31) {\n            if (checkSelfPermission("android.permission.BLUETOOTH_SCAN") != PackageManager.PERMISSION_GRANTED) permissions.add("android.permission.BLUETOOTH_SCAN");\n            if (checkSelfPermission("android.permission.BLUETOOTH_CONNECT") != PackageManager.PERMISSION_GRANTED) permissions.add("android.permission.BLUETOOTH_CONNECT");\n            if (checkSelfPermission("android.permission.BLUETOOTH_ADVERTISE") != PackageManager.PERMISSION_GRANTED) permissions.add("android.permission.BLUETOOTH_ADVERTISE");\n        }\n        if (permissions.isEmpty()) {\n            BirRelayManager.setEnabled(this, true);\n            toast(ui("B.I.R. Relay prêt.", "B.I.R. Relay ready."));\n        } else {\n            requestPermissions(permissions.toArray(new String[0]), REQUEST_RELAY_PERMISSIONS);\n        }\n    }\n\n    @Override\n    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {\n        super.onRequestPermissionsResult(requestCode, permissions, grantResults);\n        if (requestCode == REQUEST_RELAY_PERMISSIONS) {\n            boolean granted = true;\n            for (int result : grantResults) if (result != PackageManager.PERMISSION_GRANTED) granted = false;\n            if (granted && BirRelayManager.permissionsReady(this)) {\n                BirRelayManager.setEnabled(this, true);\n                toast(ui("B.I.R. Relay activé. Les échanges ne contiennent jamais le PIN.",\n                        "B.I.R. Relay enabled. Exchanges never contain the PIN."));\n            } else toast(ui("Relay reste désactivé sans l’autorisation Appareils à proximité.",\n                    "Relay remains disabled without Nearby devices permission."));\n        }\n    }\n\n'''+anchor
s=rep(s,anchor,helper,'relay permission helper')
