p='app/src/test/v290-offline-robot-contract.mjs';write(p,r'''import fs from 'node:fs';\nfunction must(path,parts){const t=fs.readFileSync(path,'utf8');for(const p of parts){if(!t.includes(p))throw new Error(path+' missing '+p)}}\nmust('app/build.gradle',['versionCode 55','versionName "2.9.0"']);\nmust('app/src/main/java/com/profitloop/blueauto/AppConfig.java',['"REMOTE"','"ROBOT"']);\nconst config=fs.readFileSync('app/src/main/java/com/profitloop/blueauto/AppConfig.java','utf8');if(config.includes('"HYBRID"'))throw new Error('HYBRID mode must not be reintroduced in Android AppConfig');\nmust('app/src/main/java/com/profitloop/blueauto/OfflineRobotEngine.java',['REQUEST_SUPPLY','LOCAL_ROBOT','SUPPLY_CHILD','RETAIL_SALE']);\nmust('app/src/main/java/com/profitloop/blueauto/RobotService.java',['OfflineLedgerDb.isLocal(command)','OfflineSyncManager.flushAsync(this)','BirRelayManager']);\nmust('app/src/main/java/com/profitloop/blueauto/BirRelayManager.java',['WIFI_DIRECT','BLUETOOTH','never carries','pendingEnvelopes']);\nmust('app/src/main/java/com/profitloop/blueauto/RelayIdentityStore.java',['AndroidKeyStore','SHA256withRSA']);\nmust('app/src/main/assets/control-tower-v290.js',['SOLDE RÉEL HORS COMMISSION','Solde global réel','B.I.R. RELAY','LIMITES CONNUES']);\nconsole.log('BIR v2.9 offline Robot contract OK');\n'''.replace('\\n','\n'))
